func firstWalkableTestPosition(t *testing.T, w *World, mapID string, x, y int) (int, int) {
	t.Helper()
	mp, ok := w.data.Maps[mapID]
	if !ok {
		t.Fatalf("map %s missing from test data", mapID)
	}
	for radius := 0; radius < 32; radius++ {
		for dy := -radius; dy <= radius; dy++ {
			for dx := -radius; dx <= radius; dx++ {
				if abs(dx) != radius && abs(dy) != radius {
					continue
				}
				candidateX, candidateY := x+dx, y+dy
				if mp.Walkable(candidateX, candidateY) {
					return candidateX, candidateY
				}
			}
		}
	}
	t.Fatalf("no walkable test position near (%d,%d) on map %s", x, y, mapID)
	return 0, 0
}

func attackMonsterForTest(w *World, ch storage.Character, monsterID string) (AttackResult, error) {
	w.mu.Lock()
	defer w.mu.Unlock()
	mon, ok := w.monsters[monsterID]
	if !ok || !mon.Alive {
		return AttackResult{}, fmt.Errorf("monster not found")
	}
	return w.attackLocked(ch, mon, mir176.CMHit)
}

func setEquippedItem(ch *storage.Character, slot int, item storage.UserItem) {
	if ch.EquippedItems == nil {
		ch.EquippedItems = map[int]storage.UserItem{}
	}
	if item.ItemID == "" {
		delete(ch.EquippedItems, slot)
		return
	}
	ch.EquippedItems[slot] = item
}

type zeroSource struct{}

func (zeroSource) Int63() int64 { return 0 }
func (zeroSource) Seed(int64)   {}

type twoSource struct{}

func (twoSource) Int63() int64 { return 2 }
func (twoSource) Seed(int64)   {}

type twentySource struct{}

func (twentySource) Int63() int64 { return 1 << 62 }
func (twentySource) Seed(int64)   {}

type seqSource struct {
	vals []int64
	idx  int
}

func (s *seqSource) Int63() int64 {
	if len(s.vals) == 0 {
		return 0
	}
	if s.idx >= len(s.vals) {
		return s.vals[len(s.vals)-1]
	}
	v := s.vals[s.idx]
	s.idx++
	return v
}

func (s *seqSource) Seed(int64) {}

