func TestRace107ProductionBehaviorsAreExplicitlyMapped(t *testing.T) {
	bundle := loadTestBundle(t)
	w := &World{}
	for id, want := range map[string]string{"宝箱": "", "宝箱1": "", "蜈蚣王": "", "触龙神": "centipede_king", "触龙神1": "centipede_king", "暗之触龙神": "centipede_king"} {
		tpl, ok := bundle.Monsters[id]
		if !ok || tpl.Behavior != want {
			t.Fatalf("monster %q behavior = %q, want %q", id, tpl.Behavior, want)
		}
		mon := &Monster{TemplateID: id, Behavior: tpl.Behavior, Race: tpl.Race}
		if tpl.Race == 107 && !w.monsterIsCentipedeLocked(mon) {
			t.Fatalf("monster %q does not use race 107 centipede behavior", id)
		}
	}
	mon := &Monster{Race: 107, Dir: 4}
	applyMonsterTemplateState(mon, data.StdMonster{Race: 107})
	if mon.Dir != 5 {
		t.Fatalf("race 107 direction = %d, want 5", mon.Dir)
	}
}

func TestArcherGuardTurnsBackWhenIdle(t *testing.T) {
	bundle := loadTestBundle(t)
	addSpawnNearDefault(t, &bundle, "弓箭护卫", 2, 0)
	store, err := storage.Open(filepath.Join(t.TempDir(), "state.json"))
	if err != nil {
		t.Fatalf("Open() error = %v", err)
	}
	w := New(bundle, store)
	primeMonsterTimersForTests(w)
	w.mu.Lock()
	var mon *Monster
	for _, candidate := range w.monsters {
		if candidate.TemplateID == "弓箭护卫" {
			mon = candidate
			break
		}
	}
	w.mu.Unlock()
	if mon == nil {
		t.Fatalf("expected spawned 弓箭护卫")
	}
	w.mu.Lock()
	mon.Dir = 1
	mon.GuardDirection = 4
	mon.TargetCharacterID = "player-1"
	w.mu.Unlock()
	ch := storage.Character{ID: "player-1", MapID: testMapID, X: mon.X + 13, Y: mon.Y, HP: 20, MaxHP: 20}
	result, err := w.Tick([]PlayerSnapshot{{Character: ch}}, time.Unix(10, 0))
	if err != nil {
		t.Fatalf("Tick() error = %v", err)
	}
	if len(result.MonsterActions) != 1 || result.MonsterActions[0].Kind != MonsterActionTurn || result.MonsterActions[0].Dir != 4 {
		t.Fatalf("MonsterActions = %+v, want turn back to guard direction", result.MonsterActions)
	}
}

