func TestCombatDropPickupKeepsRuntimeStateSeparateFromStorage(t *testing.T) {
	bundle := loadTestBundle(t)
	addSpawnNearDefault(t, &bundle, testMonsterID, 2, 0)
	path := filepath.Join(t.TempDir(), "state.json")
	store, err := storage.Open(path)
	if err != nil {
		t.Fatalf("Open() error = %v", err)
	}
	w := New(bundle, store)
	primeMonsterTimersForTests(w)
	mapID, x, y := defaultSpawn(bundle)
	ch, err := w.CreateCharacterWithAppearance("test", "tester", "warrior", 0, 0, mapID, x, y)
	if err != nil {
		t.Fatalf("CreateCharacter() error = %v", err)
	}
	ch, err = w.Move(ch, x+1, y)
	if err != nil {
		t.Fatalf("Move() error = %v", err)
	}
	storedBefore := w.mustStoredCharacter(t, ch.ID)
	monsters, _ := w.SnapshotAround(ch.MapID, 0, 0, 99999)
	if len(monsters) == 0 {
		t.Fatalf("expected monsters")
	}
	var targetMonster Monster
	for _, candidate := range monsters {
		if candidate.TemplateID == testMonsterID {
			targetMonster = candidate
			break
		}
	}
	if targetMonster.ID == "" {
		t.Fatalf("expected chicken target")
	}
	w.mu.Lock()
	w.monsters[targetMonster.ID].HP = 1
	w.mu.Unlock()
	var result AttackResult
	for i := 0; i < 10; i++ {
		result, err = attackMonsterForTest(w, ch, targetMonster.ID)
		if err != nil {
			t.Fatalf("Attack() error = %v", err)
		}
		ch = result.Character
		if result.MonsterHP == 0 {
			break
		}
	}
	tick, err := w.Tick([]PlayerSnapshot{{Character: ch}}, time.Now())
	if err != nil {
		t.Fatalf("Tick() error = %v", err)
	}
	if len(tick.MonsterDeaths) != 1 {
		t.Fatalf("monster did not die")
	}
	result = tick.MonsterDeaths[0]
	ch = result.Character
	if result.Experience == 0 {
		t.Fatalf("expected experience")
	}
	if len(result.Drops) != 0 {
		t.Fatalf("animal drops = %+v, want none", result.Drops)
	}
	corpse := targetMonster
	var butcher ButcherResult
	for i := 0; i < 20; i++ {
		butcher, err = w.ButcherAnimal(ch, MonsterActorID(corpse), corpse.X, corpse.Y, ch.Dir)
		if err == nil && butcher.FoundItem {
			break
		}
	}
	if err != nil || !butcher.FoundItem || butcher.AddedItem.ItemID != "鸡肉" {
		t.Fatalf("ButcherAnimal() = %+v, err=%v, want chicken meat", butcher, err)
	}
	if !butcher.Skeleton {
		t.Fatalf("ButcherAnimal() skeleton = false, want corpse skeletonization")
	}
	ch = butcher.Character
	reopened, err := storage.Open(path)
	if err != nil {
		t.Fatalf("reopen error = %v", err)
	}
	saved, ok := reopened.Character(ch.ID)
	if !ok {
		t.Fatalf("saved character missing")
	}
	if saved.Experience != storedBefore.Experience || saved.MapID != storedBefore.MapID || saved.X != storedBefore.X || saved.Y != storedBefore.Y || len(saved.BagItems) != len(storedBefore.BagItems) {
		t.Fatalf("stored character = %+v, want unchanged gameplay snapshot %+v", saved, storedBefore)
	}
	if ch.Experience == 0 || len(ch.BagItems) < 1 {
		t.Fatalf("runtime character = %+v, want experience and butchered meat", ch)
	}
}

func TestMonsterDeathResetsSearchCooldown(t *testing.T) {
	bundle := loadTestBundle(t)
	store, err := storage.Open(filepath.Join(t.TempDir(), "state.json"))
	if err != nil {
		t.Fatalf("Open() error = %v", err)
	}
	w := New(bundle, store)
	mon := &Monster{
		ID:                "mon-1",
		MapID:             testMapID,
		X:                 10,
		Y:                 10,
		Dir:               4,
		ViewRange:         5,
		LeashRange:        15,
		SearchNoTargetMS:  1000,
		SearchHasTargetMS: 8000,
		HP:                1,
		MaxHP:             1,
		Alive:             true,
		MinAttack:         1,
		MaxAttack:         1,
	}
	ch := storage.Character{ID: "player-1", MapID: testMapID, X: 11, Y: 10, HP: 20, MaxHP: 20}
	_, hit, err := w.monsterAttackCharacterWithDamageLocked(mon, ch, 999)
	if err != nil {
		t.Fatalf("monsterAttackCharacterWithDamageLocked() error = %v", err)
	}
	if !hit.Dead {
		t.Fatalf("hit.Dead = false, want true")
	}
	if mon.TargetCharacterID != "" {
		t.Fatalf("TargetCharacterID = %q, want empty", mon.TargetCharacterID)
	}
	if mon.TargetX != -1 || mon.TargetY != -1 {
		t.Fatalf("Target position = (%d,%d), want (-1,-1)", mon.TargetX, mon.TargetY)
	}
	if !mon.TargetFocusAt.IsZero() {
		t.Fatalf("TargetFocusAt = %v, want zero", mon.TargetFocusAt)
	}
	if mon.NextSearchAt.IsZero() {
		t.Fatalf("NextSearchAt = zero, want immediate re-search")
	}
	_, _, _, err = w.tickNormalMonsterLocked(mon, map[string]storage.Character{ch.ID: ch}, mon.NextSearchAt.Add(time.Millisecond))
	if err != nil {
		t.Fatalf("tickNormalMonsterLocked() error = %v", err)
	}
	if mon.TargetCharacterID != "" {
		t.Fatalf("TargetCharacterID = %q, want no implicit search for base TMonster", mon.TargetCharacterID)
	}
}

