	w.fireFields[fireFieldKey{MapID: mapID, X: m2.X, Y: m2.Y}] = fireField{Order: 1, MapID: mapID, X: m2.X, Y: m2.Y, OwnerID: caster.ID, Damage: 7, ExpiresAt: time.Now().Add(time.Minute), NextTick: time.Time{}}
